import java.util.*;

class Solution {
    public List<String> buildBrackets(int n) {
        List<String> out = new ArrayList<>();
        go(n, 0, 0, new StringBuilder(), out);
        return out;
    }

    private void go(int n, int open, int close, StringBuilder sb, List<String> out) {
        if (sb.length() == 2 * n) { out.add(sb.toString()); return; }
        if (open < n) {                     // can still open
            sb.append('(');
            go(n, open + 1, close, sb, out);
            sb.deleteCharAt(sb.length() - 1);
        }
        if (close < open) {                 // can close only an open bracket
            sb.append(')');
            go(n, open, close + 1, sb, out);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
}

