class Solution:
    def buildBrackets(self, n: int) -> List[str]:
        out = []
        def go(s, o, c):
            if len(s) == 2 * n: out.append(s); return
            if o < n: go(s + "(", o + 1, c)
            if c < o: go(s + ")", o, c + 1)
        go("", 0, 0)
        return out

