function buildBrackets(n) {
  const memo = [[""]];
  for (let k = 1; k <= n; k++) {
    memo[k] = [];
    for (let i = 0; i < k; i++) for (const a of memo[i]) for (const b of memo[k - 1 - i]) memo[k].push("(" + a + ")" + b);
  }
  return memo[n];
}
